ee:message.ee:set-payload:
%dw 2.0
output application/json
var cun = payload.cun
---
{
	requestHeader: {
		system: {
			name: cun.system
		}
	},
	requestBody: {
		id: "", /* No estoy seguro de donde sale el id */
		cun: cun.cunNumber,
		documentType: cun.identificationType,
		identificationNumber: cun.identification,
		orderNumber: cun.orderNumber,
		orderDetails: [{
			connectionNumber: cun.connectionNumber
		}],
		"setType": "U"
	}
}
